def find_components(grid, val):
    """Find connected components."""
    rows = len(grid)
    cols = len(grid[0])
    visited = [[False]*cols for _ in range(rows)]
    comps = []

    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == val and not visited[r][c]:
                comp = []
                stack = [(r,c)]
                visited[r][c] = True
                while stack:
                    cr, cc = stack.pop()
                    comp.append((cr, cc))
                    for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
