    cols_set = set(c for r, c in cells)
    min_r, max_r = min(rows_set), max(rows_set)
    min_c, max_c = min(cols_set), max(cols_set)

    for r in range(min_r, max_r + 1):
        for c in range(min_c, max_c + 1):
